package com.gerenciadorrural.modules.herd.infrastructure;
import com.gerenciadorrural.modules.herd.domain.MaternalRelationRepository; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JdbcMaternalRelationRepository implements MaternalRelationRepository {private final NamedParameterJdbcTemplate j;public JdbcMaternalRelationRepository(NamedParameterJdbcTemplate j){this.j=j;}private MapSqlParameterSource p(TenantId t){return new MapSqlParameterSource("tenant",t.value());}public void insert(TenantId t,UUID mother,UUID calf,UUID pregnancy){j.update("insert into app.animal_maternal_relations(tenant_id,mother_animal_id,calf_animal_id,pregnancy_id) values(:tenant,:mother,:calf,:pregnancy)",p(t).addValue("mother",mother).addValue("calf",calf).addValue("pregnancy",pregnancy));}public Optional<UUID> motherId(TenantId t,UUID calf){return j.query("select mother_animal_id from app.animal_maternal_relations where tenant_id=:tenant and calf_animal_id=:calf",p(t).addValue("calf",calf),(r,n)->r.getObject(1,UUID.class)).stream().findFirst();}public List<UUID> calfIds(TenantId t,UUID mother,int size,long offset){return j.query("select calf_animal_id from app.animal_maternal_relations where tenant_id=:tenant and mother_animal_id=:mother order by created_at desc,calf_animal_id desc limit :size offset :offset",p(t).addValue("mother",mother).addValue("size",size).addValue("offset",offset),(r,n)->r.getObject(1,UUID.class));}}
